import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    types = {}
    output = []

    def resolve_type(t):
        if t in ['void', 'errtype']:
            return t
        elif t not in types:
            return 'errtype'
        else:
            resolved = types[t]
            if resolved == t:
                return t
            else:
                types[t] = resolve_type(resolved)
                return types[t]

    def simplify_type(t):
        if t.startswith('&&'):
            return 'errtype'
        while t.endswith('*&'):
            t = t[:-2]
        if t == '&void':
            return 'errtype'
        count = t.count('&')
        t = t.replace('&', '')
        t = t.replace('*', '')
        t = 'void' + '*' * (len(t) + count - 1)
        return t

    for i in range(1, n + 1):
        line = input[i].strip()
        if line.startswith('typedef'):
